use rusqlite::{params,Connection,OptionalExtension,Transaction};
pub fn install_schema(tx:&Transaction<'_>)->rusqlite::Result<()>{tx.execute_batch("CREATE TABLE IF NOT EXISTS offline_experience_consolidation (cycle_id TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, json BLOB NOT NULL, idempotency_key TEXT NOT NULL, updated_at_ms INTEGER NOT NULL, PRIMARY KEY(cycle_id,revision), UNIQUE(cycle_id,idempotency_key)); CREATE TABLE IF NOT EXISTS offline_experience_consolidation_run (run_id TEXT PRIMARY KEY, cycle_id TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, pinned_at_ms INTEGER NOT NULL);")}
pub fn save(c:&Connection,id:&str,r:u64,h:&str,j:&[u8],k:&str,n:i64)->rusqlite::Result<()>{let old:Option<(u64,String)>=c.query_row("SELECT revision,content_hash FROM offline_experience_consolidation WHERE cycle_id=?1 AND idempotency_key=?2",params![id,k],|x|Ok((x.get(0)?,x.get(1)?))).optional()?;if let Some((or,oh))=old{if or==r&&oh==h{return Ok(())}return Err(rusqlite::Error::InvalidParameterName("consolidation idempotency conflict".into()))}let latest:Option<u64>=c.query_row("SELECT MAX(revision) FROM offline_experience_consolidation WHERE cycle_id=?1",params![id],|x|x.get(0)).optional()?.flatten();if r!=latest.unwrap_or(0)+1{return Err(rusqlite::Error::InvalidParameterName("consolidation revision conflict".into()))}c.execute("INSERT INTO offline_experience_consolidation VALUES(?1,?2,?3,?4,?5,?6)",params![id,r,h,j,k,n])?;Ok(())}
pub fn current(c:&Connection,id:&str)->rusqlite::Result<Option<Vec<u8>>>{c.query_row("SELECT json FROM offline_experience_consolidation WHERE cycle_id=?1 ORDER BY revision DESC LIMIT 1",params![id],|x|x.get(0)).optional()}
pub fn pin(c:&Connection,run_id:&str,id:&str,r:u64,h:&str,n:i64)->rusqlite::Result<()>{let old:Option<(String,u64,String)>=c.query_row("SELECT cycle_id,revision,content_hash FROM offline_experience_consolidation_run WHERE run_id=?1",params![run_id],|x|Ok((x.get(0)?,x.get(1)?,x.get(2)?))).optional()?;if let Some((oi,or,oh))=old{if oi==id&&or==r&&oh==h{return Ok(())}return Err(rusqlite::Error::InvalidParameterName("consolidation run conflict".into()))}c.execute("INSERT INTO offline_experience_consolidation_run VALUES(?1,?2,?3,?4,?5)",params![run_id,id,r,h,n])?;Ok(())}
